def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    max_prev_bid = 0.0
    pressure_bid = 0.0
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            opp_urgent = 0
            if opp.get('hp', 0) <= 3:
                opp_urgent += 1
            if opp.get('no_water_days', 0) >= 1:
                opp_urgent += 1
            if opp_urgent >= 1:
                urgent_opp_count += 1

            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid > max_prev_bid:
                    max_prev_bid = bid
                weight = 1.0
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    weight = 1.1
                if bid * weight > pressure_bid:
                    pressure_bid = bid * weight

    if not alive_opps:
        return max(0.0, min(budget, 18.0))

    my_urgent = 0
    if hp <= 3:
        my_urgent += 2
    elif hp <= 5:
        my_urgent += 1
    if no_water_days >= 1:
        my_urgent += 2

    tight_supply = supply <= 17
    roomy_supply = supply >= 22

    if my_urgent >= 3:
        bid = max(0.95 * DAILY_SALARY, pressure_bid + 2.0)
    elif my_urgent >= 2:
        if tight_supply:
            bid = max(0.82 * DAILY_SALARY, pressure_bid + 1.5)
        else:
            bid = max(0.68 * DAILY_SALARY, pressure_bid * 0.72)
    else:
        if roomy_supply:
            bid = max(14.0, min(0.38 * DAILY_SALARY, pressure_bid * 0.45))
        elif tight_supply:
            if max_prev_bid >= 120:
                bid = 0.42 * DAILY_SALARY
            else:
                bid = max(0.52 * DAILY_SALARY, pressure_bid * 0.62)
        else:
            if urgent_opp_count >= 2:
                bid = max(0.58 * DAILY_SALARY, pressure_bid * 0.75)
            else:
                bid = max(0.46 * DAILY_SALARY, pressure_bid * 0.58)

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.92)

    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    # Basic sanity
    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 1))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    # If no budget, bid 0
    if my_budget <= 0:
        return 0.0

    # Collect yesterday bids from alive opponents
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: with supply 15-25, number of winners is limited.
    # Higher supply => lower bid needed.
    if supply >= 21:
        supply_factor = 0.85
    elif supply >= 18:
        supply_factor = 1.0
    else:
        supply_factor = 1.15

    # HP safety: if low HP, prioritize survival (bid more to secure water), but cap by budget.
    if my_hp <= 2:
        hp_factor = 1.25
    elif my_hp <= 4:
        hp_factor = 1.10
    else:
        hp_factor = 0.95

    # Core strategy: anchor to fraction of daily salary, adjusted by observed pressure.
    # Aim to beat typical survivor bids without matching extreme max.
    target = DAILY_SALARY * 0.55

    if yesterday_bids:
        # If someone bid high yesterday, slightly overbid but not to the maximum.
        # Use average and highest to decide.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, avg_prev_bid * 0.95)
            target = max(target, highest_prev_bid * 0.70)
        else:
            target = max(target, avg_prev_bid * 0.85)

    bid = target * supply_factor * hp_factor

    # Ensure we don't exceed budget
    if bid > my_budget:
        bid = my_budget

    # Avoid tiny bids when we need water (no_water_days not provided reliably, so use hp)
    if my_hp <= 3 and bid < DAILY_SALARY * 0.35:
        bid = min(my_budget, DAILY_SALARY * 0.45)

    # Final clamp: non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 40.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > DAILY_SALARY:
            return min(my_status['budget'], DAILY_SALARY * 0.6)
        return min(my_status['budget'], max_prev + 5.0)

    return min(my_status['budget'], DAILY_SALARY * 0.55)
